css:
.loar-paper {
	font-family: Arial, Helvetica, sans-serif;
	color: #111;
	font-size: 9pt;
	line-height: 1.25;
	-webkit-print-color-adjust: exact !important;
	print-color-adjust: exact !important;
}
.loar-page-1 { page-break-after: always; }
.loar-page-2 { page-break-before: always; }
.loar-title {
	text-align: center;
	font-size: 14pt;
	font-weight: 800;
	color: #1e4d9c;
	margin: 0 0 12px;
}
.loar-meta {
	width: 100% !important;
	border-collapse: collapse !important;
	margin-bottom: 10px;
	table-layout: fixed;
}
.loar-meta td {
	border: 1px solid #6f7f93 !important;
	padding: 6px 7px !important;
	vertical-align: middle !important;
}
.loar-meta-label {
	width: 16%;
	background: #1e4d9c !important;
	color: #fff !important;
	font-weight: 700;
	font-size: 8pt;
	text-transform: uppercase;
}
.loar-meta-value { background: #fff !important; min-height: 28px; }
.loar-sign { max-height: 36px; max-width: 120px; }
.loar-grid {
	width: 100% !important;
	border-collapse: collapse !important;
	table-layout: fixed;
}
.loar-grid th,
.loar-grid td {
	border: 1px solid #6f7f93 !important;
	vertical-align: top;
}
.loar-grid th {
	background: #1e4d9c !important;
	color: #fff !important;
	font-weight: 800;
	font-size: 8pt;
	text-align: center;
	padding: 6px 4px !important;
	text-transform: uppercase !important;
}
.loar-th-outcome { width: 26%; }
.loar-th-criteria { width: 44%; }
.loar-th-result { width: 12%; }
.loar-th-comments { width: 18%; }
.loar-outcome {
	background: #eef3fb !important;
	font-weight: 700;
	font-size: 8pt;
	padding: 6px !important;
	vertical-align: middle !important;
}
.loar-criterion {
	padding: 5px 6px !important;
	font-size: 8.5pt;
}
.loar-num { color: #ef7a28; font-weight: 800; margin-right: 4px; }
.loar-result {
	text-align: center;
	vertical-align: middle !important;
	font-weight: 800;
	font-size: 9pt;
}
.loar-pass { color: #1e7e34; }
.loar-fail { color: #c0392b; }
.loar-comments {
	padding: 5px 6px !important;
	font-size: 8pt;
}
.loar-footer {
	margin-top: 14px;
	padding-top: 6px;
	border-top: 1.5px solid #1e4d9c;
	color: #1e4d9c;
	font-weight: 700;
	font-size: 8.5pt;
	text-align: left;
}
